package android.os;
public class Handler {private static final java.util.concurrent.ScheduledExecutorService EXEC=java.util.concurrent.Executors.newSingleThreadScheduledExecutor(r->{Thread t=new Thread(r,"tvbox-callback");t.setDaemon(true);return t;});private final java.util.Map<Runnable,java.util.List<java.util.concurrent.Future<?>>> tasks=new java.util.concurrent.ConcurrentHashMap<>();public Handler(){}public Handler(Looper l){}public boolean post(Runnable r){return postDelayed(r,0);}public boolean postDelayed(Runnable r,long delay){java.util.concurrent.Future<?> f=EXEC.schedule(r,Math.max(0,delay),java.util.concurrent.TimeUnit.MILLISECONDS);tasks.computeIfAbsent(r,k->new java.util.concurrent.CopyOnWriteArrayList<>()).add(f);return true;}public void removeCallbacks(Runnable r){java.util.List<java.util.concurrent.Future<?>> f=tasks.remove(r);if(f!=null)for(java.util.concurrent.Future<?> x:f)x.cancel(false);}public void removeCallbacksAndMessages(Object token){for(Runnable r:tasks.keySet())removeCallbacks(r);}public Looper getLooper(){return Looper.getMainLooper();}}
